// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BundleReleases) predicate.BundleReleases {
	return predicate.BundleReleases(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BundleReleases) predicate.BundleReleases {
	return predicate.BundleReleases(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundleReleases) predicate.BundleReleases {
	return predicate.BundleReleases(sql.NotPredicates(p))
}
